import{z as i,x as o,o as l,c as d,q as n,j as t,D as E,d as r,s as A,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"自我偏好","description":"","frontmatter":{"title":"自我偏好","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/self-preference-bias.md","filePath":"llm/self-preference-bias.md","lastUpdated":1791063341000}'),p={name:"llm/self-preference-bias.md"};function m(D,a,f,h,c,u){const s=o("Mermaid");return l(),d("div",null,[a[2]||(a[2]=n('<h1 id="自我偏好" tabindex="-1">自我偏好 <a class="header-anchor" href="#自我偏好" aria-label="Permalink to &quot;自我偏好&quot;">​</a></h1><div class="epigraph"><p>法官更常把「写得像我」判成更好。同族模型互评会把风格重叠写成能力差。</p><footer>—— Zheng 等的 self-enhancement；Panickssery 等对「认出并偏爱自己生成」的测量</footer></div><p><a href="/llm/style-control">上一课</a>去掉长度等可观测混淆。还剩更难观测的一种：生成器与法官共享解码先验。本课写自我偏好。缺口是：用 GPT-4 评所有人，或用自家 70B 评自家 7B，名次里含族谱。后课人评协议是为了给这条偏差一个不共享族谱的金标。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Zheng 等人报告法官偏爱自己的回答。Panickssery 等人进一步表明，LLM 评委能在一定条件下认出谁是自己的生成，并给予更高分。结果是：闭源法官定义的自动榜会系统性压低文风不同的开源模型，即使人评并不如此。</p><p>这与训练泄漏不同。即使题没见过，<strong>文风见过</strong>。换法官家族，榜会转——这是诊断，应写成稳定性报告，而不是只换到对自己有利的法官。</p><p><span class="marginnote">直觉类比：语文老师批作文，遇到与自己师出同门的学生写的句子，会莫名觉得「通顺」。LLM 法官的质量判断里就混着这种「像不像我」的熟悉感，它和真实能力无关，却会直接改写名次。</span></p><p><span class="marginnote">自我偏好在奖励模型同源时更危险：RL 对学生的奖励若由同族教师给，学生会模仿教师腔，评测再由教师打分，闭环。应至少换一族法官做敏感性分析。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>最小检测：同一批成对样本，用两个不同家族的法官，看 Kendall 名次相关；再与人评相关。相关在人–法官之间低、在同族法官之间高，则自我偏好主导。缓解：交叉法官、多数投票跨家族、或把评测法官与训练 RM 隔离。不要用「我不是那个模型」的提示禁令当缓解——证据不足。</p><p><span class="marginnote">常见误区：在提示里写一句「请勿偏爱自己生成的回答」就以为解决了。测量表明这类禁令基本无效——偏差藏在权重里，不在提示层面，所以要用换法官家族这种结构性手段，而不是提示工程。</span></p>',11)),(l(),t(B,null,{default:E(()=>[A(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E5%80%99%E9%80%89%E5%9B%9E%E5%A4%8D%22%5D%20--%3E%20J1%5B%22%E5%AE%B6%E6%97%8F%20A%20%E6%B3%95%E5%AE%98%22%5D%0A%20%20Y%20--%3E%20J2%5B%22%E5%AE%B6%E6%97%8F%20B%20%E6%B3%95%E5%AE%98%22%5D%0A%20%20J1%20--%3E%20RNK%5B%22%E5%90%8D%E6%AC%A1%22%5D%0A%20%20J2%20--%3E%20RNK%0A%20%20RNK%20--%3E%20HUM%5B%22%E4%B8%8E%E4%BA%BA%E8%AF%84%E5%AF%B9%E7%85%A7%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"同族模型共享分词、预训域与对齐配方，输出在 n-gram、列表习惯、拒答套话上更近。法官的「质量」分类器部分是密度估计：更像自己的分布就被当成更规范。认出自身还可以走更浅的捷径（特殊标记、固定签名句），评测应打乱这些表面线索，否则测到的是水印而不是能力。",-1)),a[5]||(a[5]=e("p",null,"自我偏好是怎么形成的：",-1)),(l(),t(B,null,{default:E(()=>[A(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHARE%5B%22%E5%90%8C%E6%97%8F%E5%85%B1%E4%BA%AB%EF%BC%9A%E5%88%86%E8%AF%8D%20%2F%20%E9%A2%84%E8%AE%AD%E5%9F%9F%20%2F%20%E5%AF%B9%E9%BD%90%E9%85%8D%E6%96%B9%22%5D%20--%3E%20GEN%5B%22%E7%94%9F%E6%88%90%E5%99%A8%E8%BE%93%E5%87%BA%E5%B8%A6%E5%AE%B6%E6%97%8F%E6%96%87%E9%A3%8E%22%5D%0A%20%20GEN%20--%3E%20JUDGE%5B%22%E5%90%8C%E6%97%8F%E6%B3%95%E5%AE%98%E8%AF%84%E5%88%86%22%5D%0A%20%20JUDGE%20--%3E%20DENS%5B%22%E8%B4%A8%E9%87%8F%E5%88%A4%E6%96%AD%E8%BF%91%E4%BC%BC%E5%AF%86%E5%BA%A6%E4%BC%B0%E8%AE%A1%EF%BC%9A%E5%83%8F%E8%87%AA%E5%B7%B1%20%E5%B0%B1%E7%BB%99%E9%AB%98%E5%88%86%22%5D%0A%20%20DENS%20--%3E%20BIAS%5B%22%E6%96%87%E9%A3%8E%E9%87%8D%E5%8F%A0%E8%A2%AB%E8%AE%B0%E6%88%90%E8%83%BD%E5%8A%9B%E5%B7%AE%22%5D%0A%20%20BIAS%20--%3E%20LOOP%5B%22%E8%AE%AD%E7%BB%83%20RM%20%E5%90%8C%E6%BA%90%E6%97%B6%E8%BF%9B%E4%B8%80%E6%AD%A5%E9%97%AD%E7%8E%AF%E5%BC%BA%E5%8C%96%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">为什么重要：若模型输出带固定签名句（固定开头、特殊标点），法官可能靠这些浅线索「认亲」。评测时把这些表面线索打乱或改写：分数大幅下降，说明测到的是水印；分数基本不变，才更接近真实能力差距。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写如何伪造他族文风以骗法官。下一课把金标拉回人类协议：招募、盲评、金题、疲劳。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>同族法官会把文风重叠写成胜率。</li><li>跨家族敏感性与人评相关是最低披露。</li><li>训练 RM 与评测法官应隔离。</li><li>出处：Zheng 等 LLM-as-a-Judge；Panickssery 等自我偏好测量。</li></ul>',5))])}const b=i(p,[["render",m]]);export{_ as __pageData,b as default};
